Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '--allow-anonymous', '--topic', '"shop/#;retain"', '--mqtt5-disconnect-after-retained', 'kafka://127.0.0.1:8080/', 'mqtt5://127.0.0.1:8081/' -PassThru -NoNewWindow
